import manifest from './veloop.manifest.json';

// Official VELoop design assets. Files are generated by scripts/optimize-assets.py
// (originals live in /design-source, outside the shipped bundle). Each asset has a
// width ladder in AVIF + WebP; <Asset> lets the browser pick the smallest one that
// is sharp at the size it is really painted.
const base = '/assets/veloop';
const ALT = {
  coin: 'VES coins',
  giftBurst: 'Gift box with an Amazon gift card',
  giftCard: 'Amazon gift card',
  crown: 'Ultimate reward crown',
  exclusive: 'Exclusive reward gift box',
  flame: 'Streak flame',
  stayActive: 'Calendar check-in',
  heroCrown: 'Crown on a podium with coins and gems',
  biggerStreak: 'Growing rewards chart',
};

const srcset = (stem, widths, ext) => widths.map((w) => `${base}/${stem}-${w}.${ext} ${w}w`).join(', ');

export const ASSETS = Object.fromEntries(
  Object.entries(manifest).map(([key, m]) => {
    // mid-size WebP is the plain `src` for any consumer that can't use srcset
    const mid = m.widths.find((w) => w >= 432) || m.widths[m.widths.length - 1];
    return [
      key,
      {
        w: m.w,
        h: m.h,
        alt: ALT[key] || '',
        src: `${base}/${m.stem}-${mid}.webp`,
        webp: srcset(m.stem, m.widths, 'webp'),
        avif: srcset(m.stem, m.widths, 'avif'),
        stem: m.stem,
        widths: m.widths,
      },
    ];
  }),
);

// Backend sends an asset *identifier*; this maps it to official art.
export const ASSET_FOR_TYPE = {
  coin: 'coin',
  'gift-box': 'giftBurst',
  'gift-card': 'giftCard',
  crown: 'crown',
};

// Used by index.html's preload hint and kept here so both stay in sync.
export const PRELOAD = { flame: { sizes: '100px' } };
